// Boolean
const T = x => y => x;	// True
const F = x => y => y;	// False

// if-then-else
const ifThenElse = b => x => y => b(x)(y);
/*
* like this:
* if (True) {
*    return 1;
* } else {
*    return 10;
* }
* */
console.log(ifThenElse(T)(1)(10)); // 1
console.log(ifThenElse(F)(1)(10)); // 10

