title:
// successor number.
const succ = x => x + 1;
// church numeral.
const λ0 = x => x;
const λ1 = y => x => y(x);
const λ2 = y => x => y(y(x));
const λ3 = y => x => y(y(y(x)));

// 0
console.log(λ0(0));
// λ1(succ) -> (x) => succ(x) -> x + 1
console.log(λ1(succ)(0));
// λ2(succ) -> (x) => succ(succ(x)) -> (x + 1) + 1
console.log(λ2(succ)(0));
// λ3(succ) -> (x) => succ(succ(succ(x))) -> ((x + 1) + 1) + 1
console.log(λ3(succ)(0));

